class Dsv4SglTestActor:
    async def test_gen(self):
        # Keep DeepGEMM disabled in worker process to avoid dependency drift
        # issues on heterogeneous test environments.
        os.environ["SGLANG_ENABLE_JIT_DEEPGEMM"] = "1"
        # topk_v2 uses NVCC JIT path and is flaky in some CI/container images.
        os.environ["SGLANG_OPT_USE_TOPK_V2"] = "0"
        os.environ.setdefault("NCCL_ASYNC_ERROR_HANDLING", "1")
        os.environ.setdefault("NCCL_CUMEM_ENABLE", "0")

        dist_init_addr = "127.0.0.1:10000"
        nnodes = 1
        node_rank = 0

        tp_size = 8 * nnodes
        ep_size = 8 * nnodes
        dp_size = 1
        pp_size = 1

        # model_path = "/mnt/ceph-hz1-csp/mm-base-plt2/user_xiaotaoliu/project/workspace2/gcore-dev/hf-hub/sgl-project/DeepSeek-V4-Flash-FP8/"
        # model_path = "/mnt/geminigmceph/user_yyyuuuzhang/code/gcore-dev-0710/ckpt_miniprogram_grpo_sglang/hf/150/"
        model_path = "/mnt/geminigmceph/user_yyyuuuzhang/code/gcore-dev-0710/ckpt_miniprogram_grpo_sglang//hf_fp4_fp8/150/"
        print(f"model_path: {model_path}")
        tokenizer = AutoTokenizer.from_pretrained(model_path, trust_remote_code=True)
        if tokenizer.chat_template is None:
            tokenizer.chat_template = DSV4_CHAT_TEMPLATE
        
        with patch_ctypes_for_cudart_stub():
            import sglang.srt.entrypoints.engine

        server_args = sgl.ServerArgs(
            model_path=model_path,
            tp_size=tp_size,
            ep_size=ep_size,
            dp_size=dp_size,
            pp_size=pp_size,
            enable_dp_attention=(dp_size > 1),
            dist_init_addr=dist_init_addr,
            nnodes=nnodes,
            node_rank=node_rank,
            base_gpu_id=0,
            enable_memory_saver=True,
            enable_weights_cpu_backup=True,
            mem_fraction_static=0.7,
            max_running_requests=16,
            skip_tokenizer_init=False,
            prefill_max_requests=16,
            swa_full_tokens_ratio=0.3,
        )
        llm = sgl.Engine(server_args=server_args)

        conversations = build_conversations()

        prompts = [
            tokenizer.apply_chat_template(conversation, tokenize=False, add_generation_prompt=True) for conversation in conversations
        ]
        sampling_params = {"temperature": 0.7, "top_p": 0.9, "max_new_tokens": 512}

        outputs = await llm.async_generate(prompts, sampling_params)
        assert len(outputs) == len(prompts)
        print("-" * 80)
        print("FIRST GENERATION")
        for prompt, output in zip(prompts, outputs):
            print(f"\nPrompt: {prompt[:120]}{'...' if len(prompt) > 120 else ''}")
            print(f"Generated text: {output['text']}", flush=True)
        print("-" * 80)

        from sglang.srt.managers.io_struct import (
            ReleaseMemoryOccupationReqInput,
            ResumeMemoryOccupationReqInput,
        )
        await llm.tokenizer_manager.flush_cache()
        await llm.tokenizer_manager.release_memory_occupation(
            ReleaseMemoryOccupationReqInput(), None
        )
        logging_memory_usage_details("release_memory_occupation done")

        print("release_memory_occupation done", flush=True)
        await llm.tokenizer_manager.resume_memory_occupation(
            ResumeMemoryOccupationReqInput(), None
        )
        logging_memory_usage_details("resume_memory_occupation done")
        print("resume_memory_occupation done", flush=True)

        outputs = await llm.async_generate(prompts, sampling_params)
        assert len(outputs) == len(prompts)
        print("-" * 80)
        print("SECOND GENERATION")
        for prompt, output in zip(prompts, outputs):
            print(f"\nPrompt: {prompt[:120]}{'...' if len(prompt) > 120 else ''}")
            print(f"Generated text: {output['text']}", flush=True)
        print("-" * 80)
        logging_memory_usage_details("after second generation done")
        return [out["text"] for out in outputs]


class Dsv4SglTest(unittest.IsolatedAsyncioTestCase):
    def setUp(self):
        os.environ.setdefault("RAY_ACCEL_ENV_VAR_OVERRIDE_ON_ZERO", "0")
        os.environ["SGLANG_OPT_USE_TOPK_V2"] = "0"
        ray.init()

    def tearDown(self):
        kill_all_actors_and_shutdown_ray()

    def test_gen(self):
        test_actor = ray.remote(
            num_gpus=8,
            runtime_env={
                "env_vars": {
                    "SGLANG_ENABLE_JIT_DEEPGEMM": "1",
                    "SGLANG_OPT_USE_TOPK_V2": "0",
                }
            },
        )(Dsv4SglTestActor).remote()
        outputs = ray.get(test_actor.test_gen.remote())
        assert len(outputs) == 4
        print("[driver] actor finished, received outputs.", flush=True)
